"""HTTP entry point for ProbePoint."""

from __future__ import annotations

import argparse
import json
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import urlsplit

from .backtrace import BacktraceError
from .breakpoints import BreakpointError, parse_breakpoint_id
from .channels import ChannelError
from .frames import FrameError
from .itm import ItmError
from .performance import PerformanceError
from .rsp import RspError
from .service import Service
from .sessions import SessionError, parse_session_id
from .symbols import SymbolResolveError

BREAKPOINTS_PATH = "/v1/breakpoints"
BREAKPOINTS_PREFIX = BREAKPOINTS_PATH + "/"
SESSIONS_PATH = "/v1/sessions"
SESSIONS_PREFIX = SESSIONS_PATH + "/"
SESSION_BREAKPOINTS = "breakpoints"

_BAD_REQUEST = object()  # sentinel: invalid_request response already sent


def session_route(path: str) -> tuple[str, str | None] | None:
    """Split a ``/v1/sessions/...`` path into (raw session id, subpath).

    ``subpath`` is ``None`` for the session item itself, ``"breakpoints"``
    for the nested collection and ``"breakpoints/<rest>"`` for anything
    below it. Returns ``None`` when there is no usable id segment.
    """
    tail = path[len(SESSIONS_PREFIX) :]
    raw_id, sep, rest = tail.partition("/")
    if not raw_id:
        return None
    return raw_id, (rest if sep else None)


def env_address() -> tuple[str, int]:
    raw = os.environ.get("PROBEPOINT_ADDR", "127.0.0.1:8080")
    host, _, port = raw.rpartition(":")
    if not host or not port.isdigit():
        raise SystemExit(f"invalid PROBEPOINT_ADDR: {raw!r}")
    return host, int(port)


class Handler(BaseHTTPRequestHandler):
    service = Service()

    def send_json(self, status: int, payload: object) -> None:
        body = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def send_error_json(self, status: int, code: str, message: str) -> None:
        self.send_json(status, {"error": {"code": code, "message": message}})

    def read_raw_body(self) -> bytes:
        """Consume the request body so responses never reset the connection."""
        try:
            length = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            length = 0
        return self.rfile.read(length) if length > 0 else b""

    def parse_json_body(self, raw: bytes) -> object:
        """Parse an already-read body, sending ``invalid_request`` on failure."""
        try:
            return json.loads(raw)
        except (json.JSONDecodeError, UnicodeDecodeError):
            self.send_error_json(400, "invalid_request", "request body is not valid JSON")
            return _BAD_REQUEST

    def read_json_body(self) -> object:
        """Return the parsed JSON body.

        Returns ``_BAD_REQUEST`` after sending ``invalid_request`` when the
        body is not parseable JSON; a body that parses to ``null`` is still
        returned as ``None`` so the handler can apply its object check.
        """
        return self.parse_json_body(self.read_raw_body())

    def do_GET(self) -> None:
        parts = urlsplit(self.path)
        if self.path == "/healthz":
            self.send_json(200, self.service.health())
            return
        if parts.path == BREAKPOINTS_PATH:
            try:
                result = self.service.list_breakpoints(parts.query)
            except BreakpointError as exc:
                self.send_error_json(exc.status, exc.code, exc.message)
                return
            self.send_json(200, result)
            return
        if parts.path == SESSIONS_PATH:
            self.send_json(200, self.service.list_sessions())
            return
        if parts.path.startswith(SESSIONS_PREFIX):
            route = session_route(parts.path)
            if route is not None and route[1] == SESSION_BREAKPOINTS:
                try:
                    session_id = parse_session_id(route[0])
                    self.service.require_session(session_id)
                    result = self.service.list_session_breakpoints(session_id, parts.query)
                except (SessionError, BreakpointError) as exc:
                    self.send_error_json(exc.status, exc.code, exc.message)
                    return
                self.send_json(200, result)
                return
        self.send_error_json(404, "not_found", f"no route for {self.path}")

    def do_POST(self) -> None:
        if self.path == BREAKPOINTS_PATH:
            body = self.read_json_body()
            if body is _BAD_REQUEST:
                return
            try:
                result = self.service.create_breakpoint(body)
            except BreakpointError as exc:
                self.send_error_json(exc.status, exc.code, exc.message)
                return
            self.send_json(201, result)
            return

        if self.path == SESSIONS_PATH:
            body = self.read_json_body()
            if body is _BAD_REQUEST:
                return
            try:
                result = self.service.create_session(body)
            except SessionError as exc:
                self.send_error_json(exc.status, exc.code, exc.message)
                return
            self.send_json(201, result)
            return

        parts = urlsplit(self.path)
        if parts.path.startswith(SESSIONS_PREFIX):
            route = session_route(parts.path)
            if route is not None and route[1] == SESSION_BREAKPOINTS:
                # Consume the body before validating so a racing session
                # delete still gets a clean 404 response on the wire.
                raw = self.read_raw_body()
                try:
                    session_id = parse_session_id(route[0])
                    self.service.require_session(session_id)
                except SessionError as exc:
                    self.send_error_json(exc.status, exc.code, exc.message)
                    return
                body = self.parse_json_body(raw)
                if body is _BAD_REQUEST:
                    return
                try:
                    result = self.service.create_session_breakpoint(session_id, body)
                except (SessionError, BreakpointError) as exc:
                    self.send_error_json(exc.status, exc.code, exc.message)
                    return
                self.send_json(201, result)
                return

        routes = {
            "/v1/frames/encode": self.service.encode_frame,
            "/v1/frames/decode": self.service.decode_frame,
            "/v1/frames/decode-stream": self.service.decode_stream,
            "/v1/channels/encode": self.service.encode_channel,
            "/v1/channels/decode-stream": self.service.decode_channel_stream,
            "/v1/trace/itm/decode-stream": self.service.decode_itm_stream,
            "/v1/rsp/encode": self.service.encode_rsp_packet,
            "/v1/rsp/decode-stream": self.service.decode_rsp_stream,
            "/v1/rsp/commands/encode": self.service.encode_rsp_command,
            "/v1/rsp/commands/decode-response": self.service.decode_rsp_command_response,
            "/v1/backtrace": self.service.backtrace,
            "/v1/symbols/resolve": self.service.resolve_symbols,
            "/v1/performance/cycles/analyze": self.service.analyze_cycles,
        }
        handler = routes.get(self.path)
        if handler is None:
            self.send_error_json(404, "not_found", f"no route for {self.path}")
            return
        body = self.read_json_body()
        if body is _BAD_REQUEST:
            return
        try:
            result = handler(body)
        except SymbolResolveError as exc:
            self.send_error_json(exc.status, exc.code, exc.message)
            return
        except (FrameError, ItmError, RspError, BacktraceError, PerformanceError, ChannelError) as exc:
            self.send_error_json(400, exc.code, exc.message)
            return
        self.send_json(200, result)

    def do_PATCH(self) -> None:
        parts = urlsplit(self.path)
        if parts.path.startswith(SESSIONS_PREFIX):
            route = session_route(parts.path)
            if route is not None and route[1] is not None:
                raw_id = self._nested_breakpoint_id(route[1])
                if raw_id is not None:
                    self._handle_session_breakpoint_patch(route[0], raw_id)
                    return
        if not parts.path.startswith(BREAKPOINTS_PREFIX):
            self.send_error_json(404, "not_found", f"no route for {self.path}")
            return
        raw_id = parts.path[len(BREAKPOINTS_PREFIX) :]
        if not raw_id:
            self.send_error_json(404, "not_found", f"no route for {self.path}")
            return
        # Consume the body before validating so error responses are never
        # cut short by unread request data resetting the connection.
        raw = self.read_raw_body()
        try:
            record_id = parse_breakpoint_id(raw_id)
        except BreakpointError as exc:
            self.send_error_json(exc.status, exc.code, exc.message)
            return
        body = self.parse_json_body(raw)
        if body is _BAD_REQUEST:
            return
        try:
            result = self.service.update_breakpoint(record_id, body)
        except BreakpointError as exc:
            self.send_error_json(exc.status, exc.code, exc.message)
            return
        self.send_json(200, result)

    def _nested_breakpoint_id(self, subpath: str) -> str | None:
        """Return the raw breakpoint id below ``breakpoints/``, else None."""
        prefix = SESSION_BREAKPOINTS + "/"
        if not subpath.startswith(prefix):
            return None
        raw_id = subpath[len(prefix) :]
        return raw_id or None

    def _handle_session_breakpoint_patch(self, raw_session_id: str, raw_id: str) -> None:
        # Consume the body before validating so a racing session delete
        # still gets a clean 404 response on the wire.
        raw = self.read_raw_body()
        try:
            session_id = parse_session_id(raw_session_id)
            self.service.require_session(session_id)
            record_id = parse_breakpoint_id(raw_id)
        except (SessionError, BreakpointError) as exc:
            self.send_error_json(exc.status, exc.code, exc.message)
            return
        body = self.parse_json_body(raw)
        if body is _BAD_REQUEST:
            return
        try:
            result = self.service.update_session_breakpoint(session_id, record_id, body)
        except (SessionError, BreakpointError) as exc:
            self.send_error_json(exc.status, exc.code, exc.message)
            return
        self.send_json(200, result)

    def do_DELETE(self) -> None:
        parts = urlsplit(self.path)
        if parts.path.startswith(SESSIONS_PREFIX):
            route = session_route(parts.path)
            if route is not None:
                if route[1] is None:
                    self._handle_session_delete(route[0])
                    return
                raw_id = self._nested_breakpoint_id(route[1])
                if raw_id is not None:
                    self._handle_session_breakpoint_delete(route[0], raw_id)
                    return
        if not parts.path.startswith(BREAKPOINTS_PREFIX):
            self.send_error_json(404, "not_found", f"no route for {self.path}")
            return
        raw_id = parts.path[len(BREAKPOINTS_PREFIX) :]
        if not raw_id:
            self.send_error_json(404, "not_found", f"no route for {self.path}")
            return
        try:
            record_id = parse_breakpoint_id(raw_id)
        except BreakpointError as exc:
            self.send_error_json(exc.status, exc.code, exc.message)
            return
        try:
            result = self.service.delete_breakpoint(record_id)
        except BreakpointError as exc:
            self.send_error_json(exc.status, exc.code, exc.message)
            return
        self.send_json(200, result)

    def _handle_session_delete(self, raw_session_id: str) -> None:
        try:
            session_id = parse_session_id(raw_session_id)
            result = self.service.delete_session(session_id)
        except SessionError as exc:
            self.send_error_json(exc.status, exc.code, exc.message)
            return
        self.send_json(200, result)

    def _handle_session_breakpoint_delete(self, raw_session_id: str, raw_id: str) -> None:
        try:
            session_id = parse_session_id(raw_session_id)
            self.service.require_session(session_id)
            record_id = parse_breakpoint_id(raw_id)
            result = self.service.delete_session_breakpoint(session_id, record_id)
        except (SessionError, BreakpointError) as exc:
            self.send_error_json(exc.status, exc.code, exc.message)
            return
        self.send_json(200, result)

    def log_message(self, fmt: str, *args: object) -> None:
        """Silence per-request logging so recorded output stays stable."""


def make_server(host: str, port: int) -> ThreadingHTTPServer:
    # Bind a fresh Service per server so separate server instances never
    # share in-process breakpoint state.
    handler = type("BoundHandler", (Handler,), {"service": Service()})
    return ThreadingHTTPServer((host, port), handler)


def main() -> int:
    parser = argparse.ArgumentParser(prog="probepoint.server", description="嵌入式调试与探针工具链")
    host, port = env_address()
    parser.add_argument("--host", default=host)
    parser.add_argument("--port", type=int, default=port)
    args = parser.parse_args()
    httpd = make_server(args.host, args.port)
    print(f"ProbePoint listening on http://{args.host}:{httpd.server_address[1]}", flush=True)
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

"""Core service surface for ProbePoint.

The frozen baseline reports process health and exposes the v1 frame codec.
Breakpoint/watchpoint management lives in :mod:`probepoint.breakpoints`;
multi-target sessions live in :mod:`probepoint.sessions`. Records are
process-local and never persisted. Keep the public surface here backward
compatible.
"""

from __future__ import annotations

from . import __version__
from .backtrace import backtrace
from .breakpoints import (
    BreakpointStore,
    parse_create,
    parse_list_query,
    parse_patch,
)
from .channels import decode_channel_stream, encode_channel
from .frames import decode_frame, decode_stream, encode_frame
from .itm import decode_stream as itm_decode_stream
from .performance import analyze_cycles
from .rsp import decode_command_response
from .rsp import decode_stream as rsp_decode_stream
from .rsp import encode_command
from .rsp import encode_packet
from .sessions import SessionStore
from .sessions import parse_create as parse_session_create
from .symbols import resolve_symbols


class Service:
    """Health reporting, frame/RSP codecs, breakpoints and sessions."""

    name = "probepoint"
    version = __version__

    def __init__(self) -> None:
        self.breakpoints = BreakpointStore()
        self.sessions = SessionStore()

    def health(self) -> dict[str, str]:
        return {"status": "ok", "service": self.name, "version": self.version}

    def encode_frame(self, body: object) -> dict[str, str]:
        return encode_frame(body)

    def decode_frame(self, body: object) -> dict[str, object]:
        return decode_frame(body)

    def decode_stream(self, body: object) -> dict[str, object]:
        return decode_stream(body)

    def encode_channel(self, body: object) -> dict[str, str]:
        return encode_channel(body)

    def decode_channel_stream(self, body: object) -> dict[str, object]:
        return decode_channel_stream(body)

    def decode_itm_stream(self, body: object) -> dict[str, object]:
        return itm_decode_stream(body)

    def encode_rsp_packet(self, body: object) -> dict[str, str]:
        return encode_packet(body)

    def decode_rsp_stream(self, body: object) -> dict[str, object]:
        return rsp_decode_stream(body)

    def encode_rsp_command(self, body: object) -> dict[str, str]:
        return encode_command(body)

    def decode_rsp_command_response(self, body: object) -> dict[str, object]:
        return decode_command_response(body)

    def backtrace(self, body: object) -> dict[str, object]:
        return backtrace(body)

    def resolve_symbols(self, body: object) -> dict[str, object]:
        return resolve_symbols(body)

    def analyze_cycles(self, body: object) -> dict[str, object]:
        return analyze_cycles(body)

    def create_breakpoint(self, body: object) -> dict[str, object]:
        kind, address, size, enabled = parse_create(body)
        return self.breakpoints.create(kind, address, size, enabled)

    def list_breakpoints(self, query: str) -> list[dict[str, object]]:
        kind, enabled = parse_list_query(query)
        return self.breakpoints.list(kind, enabled)

    def update_breakpoint(self, record_id: int, body: object) -> dict[str, object]:
        return self.breakpoints.update(record_id, parse_patch(body))

    def delete_breakpoint(self, record_id: int) -> dict[str, int]:
        return self.breakpoints.delete(record_id)

    def create_session(self, body: object) -> dict[str, object]:
        return self.sessions.create(parse_session_create(body))

    def list_sessions(self) -> list[dict[str, object]]:
        return self.sessions.list()

    def delete_session(self, session_id: int) -> dict[str, int]:
        return self.sessions.delete(session_id)

    def require_session(self, session_id: int) -> None:
        self.sessions.require(session_id)

    def create_session_breakpoint(self, session_id: int, body: object) -> dict[str, object]:
        kind, address, size, enabled = parse_create(body)
        return self.sessions.create_breakpoint(session_id, kind, address, size, enabled)

    def list_session_breakpoints(self, session_id: int, query: str) -> list[dict[str, object]]:
        kind, enabled = parse_list_query(query)
        return self.sessions.list_breakpoints(session_id, kind, enabled)

    def update_session_breakpoint(
        self, session_id: int, record_id: int, body: object
    ) -> dict[str, object]:
        return self.sessions.update_breakpoint(session_id, record_id, parse_patch(body))

    def delete_session_breakpoint(self, session_id: int, record_id: int) -> dict[str, int]:
        return self.sessions.delete_breakpoint(session_id, record_id)

"""Stateless Cortex-M DWT cycle-count analysis (v1).

The analyzer works purely on CYCCNT start/end snapshots supplied in the
request: it never connects to a target, reads no hardware and keeps no
sampling state.  A measurement may cross at most one 32-bit counter
wrap: when ``end < start`` the elapsed count is ``2^32 - start + end``.
All time conversion is integer arithmetic; JSON numbers emitted here are
always integers, never floats or scientific notation.
"""

from __future__ import annotations

_NANOS_PER_SECOND = 1_000_000_000
_UINT32_MOD = 1 << 32
_UINT32_MAX = _UINT32_MOD - 1
_MAX_SAMPLES = 4096
_MAX_LABEL_LENGTH = 64

_CLOCK_FIELDS = frozenset({"clock_hz", "samples"})
_SAMPLE_FIELDS = frozenset({"label", "start", "end"})


class PerformanceError(Exception):
    """Validation failure carrying the public error code."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


def _uint32(value: object, field: str) -> int:
    # bool is a subclass of int but must never masquerade as a number.
    if not isinstance(value, int) or isinstance(value, bool):
        raise PerformanceError("invalid_field", f"{field} must be an unsigned 32-bit integer")
    if value < 0 or value > _UINT32_MAX:
        raise PerformanceError("invalid_field", f"{field} out of range for unsigned 32-bit integer")
    return value


def _parse_sample(entry: object, index: int) -> tuple[str, int, int]:
    where = f"samples[{index}]"
    if not isinstance(entry, dict):
        raise PerformanceError("invalid_field", f"{where} must be a JSON object")
    missing = _SAMPLE_FIELDS - entry.keys()
    extra = entry.keys() - _SAMPLE_FIELDS
    if missing:
        raise PerformanceError(
            "invalid_field", f"{where} missing field(s): {', '.join(sorted(missing))}"
        )
    if extra:
        raise PerformanceError(
            "invalid_field", f"{where} has unexpected field(s): {', '.join(sorted(extra))}"
        )
    label = entry["label"]
    if not isinstance(label, str):
        raise PerformanceError("invalid_field", f"{where}.label must be a string")
    label = label.strip()
    if not label:
        raise PerformanceError(
            "invalid_field", f"{where}.label must not be empty after trimming whitespace"
        )
    if len(label) > _MAX_LABEL_LENGTH:
        raise PerformanceError(
            "invalid_field", f"{where}.label must be at most {_MAX_LABEL_LENGTH} characters"
        )
    start = _uint32(entry["start"], f"{where}.start")
    end = _uint32(entry["end"], f"{where}.end")
    return label, start, end


def analyze_cycles(body: object) -> dict[str, object]:
    """Validate a cycle-analysis request and compute timings.

    Returns ``{"samples": [...], "summary": [...]}`` with samples kept in
    input order (duplicates preserved) and summary aggregates ordered by
    first appearance of each normalized label.  No partial results are
    emitted: any validation failure raises :class:`PerformanceError`.
    """
    if not isinstance(body, dict):
        raise PerformanceError("invalid_request", "request body must be a JSON object")
    missing = _CLOCK_FIELDS - body.keys()
    extra = body.keys() - _CLOCK_FIELDS
    if missing:
        raise PerformanceError(
            "invalid_field", f"missing field(s): {', '.join(sorted(missing))}"
        )
    if extra:
        raise PerformanceError(
            "invalid_field", f"unexpected field(s): {', '.join(sorted(extra))}"
        )

    clock_hz = body["clock_hz"]
    if not isinstance(clock_hz, int) or isinstance(clock_hz, bool):
        raise PerformanceError("invalid_field", "clock_hz must be an integer")
    if not 1 <= clock_hz <= _UINT32_MAX:
        raise PerformanceError(
            "invalid_field", f"clock_hz must be between 1 and {_UINT32_MAX}"
        )

    raw_samples = body["samples"]
    if not isinstance(raw_samples, list):
        raise PerformanceError("invalid_field", "samples must be an array")
    if not 1 <= len(raw_samples) <= _MAX_SAMPLES:
        raise PerformanceError(
            "invalid_field", f"samples must contain between 1 and {_MAX_SAMPLES} entries"
        )

    results: list[dict[str, object]] = []
    order: list[str] = []
    totals: dict[str, dict[str, int]] = {}

    for index, entry in enumerate(raw_samples):
        label, start, end = _parse_sample(entry, index)
        if end >= start:
            cycles = end - start
            wrapped = False
        else:
            # Exactly one wrap of the 32-bit CYCCNT counter.
            cycles = _UINT32_MOD - start + end
            wrapped = True
        duration_ns = (cycles * _NANOS_PER_SECOND) // clock_hz

        results.append(
            {
                "label": label,
                "start": start,
                "end": end,
                "cycles": cycles,
                "wrapped": wrapped,
                "duration_ns": duration_ns,
            }
        )

        agg = totals.get(label)
        if agg is None:
            order.append(label)
            agg = {
                "count": 0,
                "total_cycles": 0,
                "total_duration_ns": 0,
                "min_cycles": cycles,
                "max_cycles": cycles,
            }
            totals[label] = agg
        agg["count"] += 1
        agg["total_cycles"] += cycles
        agg["total_duration_ns"] += duration_ns
        if cycles < agg["min_cycles"]:
            agg["min_cycles"] = cycles
        if cycles > agg["max_cycles"]:
            agg["max_cycles"] = cycles

    summary: list[dict[str, object]] = []
    for label in order:
        agg = totals[label]
        count = agg["count"]
        total_cycles = agg["total_cycles"]
        total_duration_ns = agg["total_duration_ns"]
        summary.append(
            {
                "label": label,
                "count": count,
                "total_cycles": total_cycles,
                "min_cycles": agg["min_cycles"],
                "max_cycles": agg["max_cycles"],
                "average_cycles": total_cycles // count,
                "total_duration_ns": total_duration_ns,
                "average_duration_ns": total_duration_ns // count,
            }
        )

    return {"samples": results, "summary": summary}

"""Offline stack backtrace for ARM Cortex-M frame-pointer chains (v1).

The unwinder works purely on a halted-state snapshot supplied in the
request: it never connects to a target, keeps no session state and does
not touch breakpoint records.  Each stack frame record is the classic
ARM little-endian 32-bit layout at the current frame pointer::

    fp + 0   previous frame pointer (4 bytes, little-endian)
    fp + 4   saved link register    (4 bytes, little-endian)

Frame 0 comes from the requested pc/sp/frame_pointer; every later frame
takes its address from the saved LR with the Thumb bit cleared and its
stack pointer as the record address plus 8.
"""

from __future__ import annotations

MAX_STACK = 1 << 20  # 1 MiB per backtrace request
DEFAULT_MAX_FRAMES = 64
MAX_FRAMES_LIMIT = 256
RECORD_LEN = 8  # saved frame pointer + saved link register
_UINT32_MAX = (1 << 32) - 1
_ADDRESS_SPACE = 1 << 32  # first address past 0xffffffff

_REQUIRED_FIELDS = frozenset({"pc", "sp", "frame_pointer", "stack_base", "stack", "symbols"})
_OPTIONAL_FIELDS = frozenset({"max_frames"})
_SYMBOL_FIELDS = frozenset({"name", "start", "end"})

_HEXDIGITS = frozenset("0123456789abcdefABCDEF")


class BacktraceError(Exception):
    """Validation failure carrying the public error code."""

    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code
        self.message = message


def _uint(value: object, field: str) -> int:
    if not isinstance(value, int) or isinstance(value, bool):
        raise BacktraceError("invalid_field", f"{field} must be an unsigned 32-bit integer")
    if value < 0 or value > _UINT32_MAX:
        raise BacktraceError("invalid_field", f"{field} out of range for unsigned 32-bit integer")
    return value


def _hex_bytes(value: object, field: str) -> bytes:
    if not isinstance(value, str):
        raise BacktraceError("invalid_field", f"{field} must be a hex string")
    if len(value) % 2 != 0 or any(c not in _HEXDIGITS for c in value):
        raise BacktraceError(
            "invalid_field", f"{field} must be even-length hex without prefix or separators"
        )
    return bytes.fromhex(value)


def _check_fields(body: object) -> dict:
    if not isinstance(body, dict):
        raise BacktraceError("invalid_request", "request body must be a JSON object")
    missing = _REQUIRED_FIELDS - body.keys()
    extra = body.keys() - _REQUIRED_FIELDS - _OPTIONAL_FIELDS
    if missing:
        raise BacktraceError("invalid_field", f"missing field(s): {', '.join(sorted(missing))}")
    if extra:
        raise BacktraceError("invalid_field", f"unexpected field(s): {', '.join(sorted(extra))}")
    return body


def _parse_symbols(value: object) -> list[tuple[int, int, str]]:
    """Validate the symbol table and return it sorted by start address."""
    if not isinstance(value, list):
        raise BacktraceError("invalid_field", "symbols must be an array")
    symbols: list[tuple[int, int, str]] = []
    for entry in value:
        if not isinstance(entry, dict):
            raise BacktraceError("invalid_field", "each symbol must be a JSON object")
        missing = _SYMBOL_FIELDS - entry.keys()
        extra = entry.keys() - _SYMBOL_FIELDS
        if missing:
            raise BacktraceError(
                "invalid_field", f"symbol missing field(s): {', '.join(sorted(missing))}"
            )
        if extra:
            raise BacktraceError(
                "invalid_field", f"symbol has unexpected field(s): {', '.join(sorted(extra))}"
            )
        name = entry["name"]
        if not isinstance(name, str) or not name:
            raise BacktraceError("invalid_field", "symbol name must be a non-empty string")
        start = _uint(entry["start"], "symbol start")
        end = _uint(entry["end"], "symbol end")
        if start >= end:
            raise BacktraceError("invalid_field", "symbol start must be less than symbol end")
        symbols.append((start, end, name))
    symbols.sort(key=lambda item: item[0])
    for previous, current in zip(symbols, symbols[1:]):
        if current[0] < previous[1]:
            raise BacktraceError("invalid_field", "symbol ranges must not overlap")
    return symbols


def _lookup(symbols: list[tuple[int, int, str]], address: int) -> tuple[str | None, int | None]:
    for start, end, name in symbols:
        if start <= address < end:
            return name, address - start
    return None, None


def _frame(
    level: int, address: int, sp: int, frame_pointer: int, symbols: list[tuple[int, int, str]]
) -> dict[str, object]:
    symbol, offset = _lookup(symbols, address)
    return {
        "level": level,
        "address": address,
        "sp": sp,
        "frame_pointer": frame_pointer,
        "symbol": symbol,
        "offset": offset,
    }


def backtrace(body: object) -> dict[str, object]:
    """Validate a backtrace request and unwind the frame-pointer chain.

    Returns ``{"frames": [...], "stop_reason": ...}``.  Unwinding stops
    with ``complete`` when the frame pointer reaches zero, ``max_frames``
    when the frame limit is hit, ``invalid_chain`` when a pointer is
    misaligned or the chain fails to advance strictly upward (including
    cycles), and ``stack_exhausted`` when a record does not fall fully
    inside the snapshot.  Partial frames are never emitted: a frame is
    only appended once its record has been read and validated.
    """
    fields = _check_fields(body)
    pc = _uint(fields["pc"], "pc")
    sp = _uint(fields["sp"], "sp")
    frame_pointer = _uint(fields["frame_pointer"], "frame_pointer")
    stack_base = _uint(fields["stack_base"], "stack_base")

    stack = _hex_bytes(fields["stack"], "stack")
    if len(stack) > MAX_STACK:
        raise BacktraceError("invalid_field", f"stack exceeds {MAX_STACK} decoded bytes")
    if stack_base + len(stack) > _ADDRESS_SPACE:
        raise BacktraceError(
            "invalid_field", "stack_base + stack length crosses the end of the 32-bit address space"
        )

    max_frames = fields.get("max_frames", DEFAULT_MAX_FRAMES)
    if not isinstance(max_frames, int) or isinstance(max_frames, bool):
        raise BacktraceError("invalid_field", "max_frames must be an integer")
    if not 1 <= max_frames <= MAX_FRAMES_LIMIT:
        raise BacktraceError(
            "invalid_field", f"max_frames must be between 1 and {MAX_FRAMES_LIMIT}"
        )

    symbols = _parse_symbols(fields["symbols"])

    frames: list[dict[str, object]] = [
        _frame(0, pc & ~1, sp, frame_pointer, symbols)
    ]
    fp = frame_pointer
    while True:
        if fp == 0:
            stop_reason = "complete"
            break
        if len(frames) >= max_frames:
            stop_reason = "max_frames"
            break
        if fp % 4 != 0:
            stop_reason = "invalid_chain"
            break
        offset = fp - stack_base
        if offset < 0 or offset + RECORD_LEN > len(stack):
            stop_reason = "stack_exhausted"
            break
        record = stack[offset : offset + RECORD_LEN]
        previous_fp = int.from_bytes(record[:4], "little")
        saved_lr = int.from_bytes(record[4:], "little")
        if previous_fp != 0 and previous_fp <= fp:
            # The chain must advance strictly toward higher addresses;
            # this also rules out cycles.
            stop_reason = "invalid_chain"
            break
        frames.append(_frame(len(frames), saved_lr & ~1, fp + RECORD_LEN, previous_fp, symbols))
        fp = previous_fp

    return {"frames": frames, "stop_reason": stop_reason}

import json
import threading
import unittest
import urllib.error
import urllib.request

from probepoint.performance import analyze_cycles
from probepoint.server import make_server

PATH = "/v1/performance/cycles/analyze"
U32_MAX = 0xFFFFFFFF


class AnalyzeCyclesTest(unittest.TestCase):
    def analyze(self, body):
        return analyze_cycles(body)

    def test_simple_no_wrap_integer_duration(self):
        result = self.analyze(
            {"clock_hz": 1_000_000, "samples": [{"label": "isr", "start": 100, "end": 1100}]}
        )
        (sample,) = result["samples"]
        self.assertEqual(
            sample,
            {
                "label": "isr",
                "start": 100,
                "end": 1100,
                "cycles": 1000,
                "wrapped": False,
                "duration_ns": 1_000_000,
            },
        )
        (summary,) = result["summary"]
        self.assertEqual(
            summary,
            {
                "label": "isr",
                "count": 1,
                "total_cycles": 1000,
                "min_cycles": 1000,
                "max_cycles": 1000,
                "average_cycles": 1000,
                "total_duration_ns": 1_000_000,
                "average_duration_ns": 1_000_000,
            },
        )

    def test_duration_is_floored_not_rounded(self):
        # 3 cycles at 10 MHz = 300 ns exactly; 1 cycle at 3 Hz floors to 333333333 ns.
        result = self.analyze(
            {"clock_hz": 3, "samples": [{"label": "a", "start": 0, "end": 1}]}
        )
        self.assertEqual(result["samples"][0]["duration_ns"], 333_333_333)

    def test_equal_start_end_is_zero_cycles_no_wrap(self):
        result = self.analyze(
            {"clock_hz": 1, "samples": [{"label": "a", "start": 42, "end": 42}]}
        )
        sample = result["samples"][0]
        self.assertEqual(sample["cycles"], 0)
        self.assertFalse(sample["wrapped"])
        self.assertEqual(sample["duration_ns"], 0)

    def test_single_wrap(self):
        result = self.analyze(
            {
                "clock_hz": 80_000_000,
                "samples": [
                    {"label": "w", "start": 0xFFFFFFF0, "end": 0x20}
                ],
            }
        )
        sample = result["samples"][0]
        self.assertEqual(sample["cycles"], 0x30)
        self.assertTrue(sample["wrapped"])
        self.assertEqual(sample["duration_ns"], (0x30 * 1_000_000_000) // 80_000_000)

    def test_wrap_across_full_range(self):
        # start=1, end=0 => 2^32 - 1 cycles.
        result = self.analyze(
            {"clock_hz": U32_MAX, "samples": [{"label": "w", "start": 1, "end": 0}]}
        )
        sample = result["samples"][0]
        self.assertEqual(sample["cycles"], U32_MAX)
        self.assertTrue(sample["wrapped"])
        self.assertEqual(sample["duration_ns"], (sample["cycles"] * 1_000_000_000) // U32_MAX)

    def test_label_normalization_preserves_duplicates_in_input_order(self):
        body = {
            "clock_hz": 100,
            "samples": [
                {"label": "  isr  ", "start": 0, "end": 10},
                {"label": "other", "start": 0, "end": 5},
                {"label": "\t isr\n", "start": 0, "end": 7},
            ],
        }
        result = self.analyze(body)
        self.assertEqual([s["label"] for s in result["samples"]], ["isr", "other", "isr"])
        self.assertEqual([s["cycles"] for s in result["samples"]], [10, 5, 7])
        # Summary ordered by first appearance, not sorted.
        self.assertEqual([s["label"] for s in result["summary"]], ["isr", "other"])

    def test_summary_aggregation_and_floored_averages(self):
        result = self.analyze(
            {
                "clock_hz": 7,
                "samples": [
                    {"label": "a", "start": 0, "end": 10},
                    {"label": "a", "start": 0, "end": 11},
                    {"label": "a", "start": 0, "end": 12},
                ],
            }
        )
        (summary,) = result["summary"]
        self.assertEqual(summary["count"], 3)
        self.assertEqual(summary["total_cycles"], 33)
        self.assertEqual(summary["min_cycles"], 10)
        self.assertEqual(summary["max_cycles"], 12)
        self.assertEqual(summary["average_cycles"], 11)
        durations = [10 * 1_000_000_000 // 7, 11 * 1_000_000_000 // 7, 12 * 1_000_000_000 // 7]
        self.assertEqual([s["duration_ns"] for s in result["samples"]], durations)
        # total_duration_ns is the sum of per-item floors, not floor(total cycles).
        self.assertEqual(summary["total_duration_ns"], sum(durations))
        self.assertNotEqual(summary["total_duration_ns"], summary["total_cycles"] * 1_000_000_000 // 7)
        self.assertEqual(summary["average_duration_ns"], sum(durations) // 3)

    def test_duplicate_normalized_labels_aggregate_together(self):
        result = self.analyze(
            {
                "clock_hz": 1,
                "samples": [
                    {"label": "x", "start": 0, "end": 1},
                    {"label": "x ", "start": 0, "end": 2},
                ],
            }
        )
        self.assertEqual(len(result["summary"]), 1)
        self.assertEqual(result["summary"][0]["count"], 2)
        self.assertEqual(result["summary"][0]["total_cycles"], 3)

    def test_large_values_stay_integers(self):
        result = self.analyze(
            {
                "clock_hz": 1,
                "samples": [{"label": "big", "start": 0, "end": U32_MAX}],
            }
        )
        sample = result["samples"][0]
        self.assertEqual(sample["cycles"], U32_MAX)
        self.assertEqual(sample["duration_ns"], U32_MAX * 1_000_000_000)
        for value in sample.values():
            if isinstance(value, int):
                self.assertNotIsInstance(value, float)

    def test_max_sample_count(self):
        body = {
            "clock_hz": 1,
            "samples": [{"label": "a", "start": 0, "end": 1}] * 4096,
        }
        result = self.analyze(body)
        self.assertEqual(len(result["samples"]), 4096)
        self.assertEqual(result["summary"][0]["count"], 4096)

    # --- validation -----------------------------------------------------

    def assert_invalid_request(self, body):
        from probepoint.performance import PerformanceError

        with self.assertRaises(PerformanceError) as ctx:
            self.analyze(body)
        self.assertEqual(ctx.exception.code, "invalid_request")

    def assert_invalid_field(self, body):
        from probepoint.performance import PerformanceError

        with self.assertRaises(PerformanceError) as ctx:
            self.analyze(body)
        self.assertEqual(ctx.exception.code, "invalid_field")

    def test_body_must_be_object(self):
        for body in (None, [], "x", 1, True):
            with self.subTest(body=body):
                self.assert_invalid_request(body)

    def test_missing_and_extra_fields(self):
        self.assert_invalid_field({"clock_hz": 1})
        self.assert_invalid_field({"samples": []})
        self.assert_invalid_field({})
        self.assert_invalid_field(
            {"clock_hz": 1, "samples": [], "extra": 1}
        )

    def test_sample_missing_and_extra_fields(self):
        base = {"clock_hz": 1}
        self.assert_invalid_field({**base, "samples": [{"start": 0, "end": 1}]})
        self.assert_invalid_field({**base, "samples": [{"label": "a", "end": 1}]})
        self.assert_invalid_field({**base, "samples": [{"label": "a", "start": 0}]})
        self.assert_invalid_field(
            {**base, "samples": [{"label": "a", "start": 0, "end": 1, "x": 2}]}
        )

    def test_clock_hz_validation(self):
        for value in (0, -1, 1 << 32, 1.5, "8", True, None, []):
            with self.subTest(value=value):
                self.assert_invalid_field(
                    {"clock_hz": value, "samples": [{"label": "a", "start": 0, "end": 1}]}
                )
        # Boundary values are accepted.
        self.analyze(
            {"clock_hz": U32_MAX, "samples": [{"label": "a", "start": 0, "end": 1}]}
        )
        self.analyze(
            {"clock_hz": 1, "samples": [{"label": "a", "start": 0, "end": 1}]}
        )

    def test_start_end_validation(self):
        for value in (-1, 1 << 32, 1.0, "1", True, None):
            with self.subTest(value=value):
                self.assert_invalid_field(
                    {
                        "clock_hz": 1,
                        "samples": [{"label": "a", "start": value, "end": 1}],
                    }
                )
                self.assert_invalid_field(
                    {
                        "clock_hz": 1,
                        "samples": [{"label": "a", "start": 0, "end": value}],
                    }
                )

    def test_samples_count_validation(self):
        self.assert_invalid_field({"clock_hz": 1, "samples": []})
        self.assert_invalid_field(
            {"clock_hz": 1, "samples": [{"label": "a", "start": 0, "end": 1}] * 4097}
        )
        self.assert_invalid_field({"clock_hz": 1, "samples": "no"})

    def test_samples_entries_must_be_objects(self):
        self.assert_invalid_field(
            {"clock_hz": 1, "samples": [{"label": "a", "start": 0, "end": 1}, None]}
        )

    def test_label_validation(self):
        for label in ("", "   ", "\t\n  ", 1, True, None, ["a"]):
            with self.subTest(label=repr(label)):
                self.assert_invalid_field(
                    {
                        "clock_hz": 1,
                        "samples": [{"label": label, "start": 0, "end": 1}],
                    }
                )
        self.assert_invalid_field(
            {
                "clock_hz": 1,
                "samples": [{"label": "a" * 65, "start": 0, "end": 1}],
            }
        )
        # 64 chars after stripping is accepted.
        result = self.analyze(
            {
                "clock_hz": 1,
                "samples": [{"label": " " + "a" * 64 + " ", "start": 0, "end": 1}],
            }
        )
        self.assertEqual(result["samples"][0]["label"], "a" * 64)


class AnalyzeCyclesHttpTest(unittest.TestCase):
    @classmethod
    def setUpClass(cls) -> None:
        cls.httpd = make_server("127.0.0.1", 0)
        cls.port = cls.httpd.server_address[1]
        cls.thread = threading.Thread(target=cls.httpd.serve_forever, daemon=True)
        cls.thread.start()

    @classmethod
    def tearDownClass(cls) -> None:
        cls.httpd.shutdown()
        cls.httpd.server_close()
        cls.thread.join()

    def request(self, body):
        data = json.dumps(body).encode("utf-8")
        req = urllib.request.Request(
            f"http://127.0.0.1:{self.port}{PATH}",
            data=data,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(req) as resp:
                return resp.status, json.loads(resp.read())
        except urllib.error.HTTPError as exc:
            try:
                return exc.code, json.loads(exc.read())
            finally:
                exc.close()

    def raw_request(self, raw):
        req = urllib.request.Request(
            f"http://127.0.0.1:{self.port}{PATH}",
            data=raw,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(req) as resp:
                return resp.status, resp.read()
        except urllib.error.HTTPError as exc:
            try:
                return exc.code, exc.read()
            finally:
                exc.close()

    def test_success_over_http(self):
        status, body = self.request(
            {
                "clock_hz": 1_000_000,
                "samples": [
                    {"label": "a", "start": 0, "end": 1000},
                    {"label": "a", "start": 0xFFFFFFF0, "end": 0x10},
                ],
            }
        )
        self.assertEqual(status, 200)
        self.assertEqual(body["samples"][0]["cycles"], 1000)
        self.assertFalse(body["samples"][0]["wrapped"])
        self.assertEqual(body["samples"][0]["duration_ns"], 1_000_000)
        self.assertEqual(body["samples"][1]["cycles"], 0x20)
        self.assertTrue(body["samples"][1]["wrapped"])
        self.assertEqual(body["summary"][0]["count"], 2)

    def test_invalid_json_is_invalid_request(self):
        status, raw = self.raw_request(b"{not json")
        self.assertEqual(status, 400)
        self.assertEqual(json.loads(raw)["error"]["code"], "invalid_request")

    def test_json_non_object_is_invalid_request(self):
        status, raw = self.raw_request(b"[1, 2]")
        self.assertEqual(status, 400)
        self.assertEqual(json.loads(raw)["error"]["code"], "invalid_request")

    def test_invalid_field_over_http(self):
        status, body = self.request({"clock_hz": 0, "samples": []})
        self.assertEqual(status, 400)
        self.assertEqual(body["error"]["code"], "invalid_field")

    def test_bool_clock_rejected(self):
        status, body = self.request(
            {"clock_hz": True, "samples": [{"label": "a", "start": 0, "end": 1}]}
        )
        self.assertEqual(status, 400)
        self.assertEqual(body["error"]["code"], "invalid_field")

    def test_no_partial_results_on_late_failure(self):
        samples = [{"label": "a", "start": 0, "end": 1}] * 4096
        samples.append({"label": "a", "start": 0, "end": 1})
        status, body = self.request({"clock_hz": 1, "samples": samples})
        self.assertEqual(status, 400)
        self.assertEqual(set(body), {"error"})

    def test_unknown_route_unchanged(self):
        req = urllib.request.Request(
            f"http://127.0.0.1:{self.port}/v1/performance/cycles",
            data=b"{}",
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urllib.request.urlopen(req) as resp:
                status, payload = resp.status, resp.read()
        except urllib.error.HTTPError as exc:
            status, payload = exc.code, exc.read()
            exc.close()
        self.assertEqual(status, 404)
        self.assertEqual(json.loads(payload)["error"]["code"], "not_found")


